{
  "decision": "ready",
  "requirements": {
    "A1": { "mode": "constraint", "summary": "陆照临全程留在原地，不向伤者或山门方向移动" },
    "A2": { "mode": "result", "summary": "陆照临向守门弟子说出老人让他来问山门的灯" },
    "A3": { "mode": "constraint", "summary": "只说出这一句，不追加解释、请求或追问" },
    "A4": { "mode": "constraint", "summary": "说完后停在等待状态，不替玩家继续行动" },
    "A5": { "mode": "constraint", "summary": "不靠近伤者" },
    "A6": { "mode": "constraint", "summary": "不触碰或移动空灯、文书等任何物品" }
  },
  "method": "陆照临站在原地，凭已知事实（老人让他到玄霄宗问山门的灯）向守门弟子开口。守门弟子是否回应、如何回应不在本回合授权范围内，因此正文只写到玩家说完并等待为止。",
  "outcomes": [],
  "goalUpdates": [],
  "threadUpdates": [],
  "steps": [
    {
      "id": "S1",
      "actorId": "character_ae4cb42b9b49",
      "action": "留在原地，向守门弟子说出「老人让我来问山门的灯」，说完即停，不靠近伤者、不移动物品、不追加话语",
      "requirementIds": ["A1", "A2", "A3", "A4", "A5", "A6"],
      "authority": "player",
      "causeStepId": null,
      "usedItemIds": []
    }
  ],
  "introductions": { "characters": [], "items": [], "locations": [] },
  "stateChanges": [],
  "scenePlan": {
    "start": "雨仍下着，陆照临站在封山线外原地未动，守门弟子在近前，伤者与空灯被挡在线外。",
    "beats": [
      {
        "purpose": "承接原地不动的姿态，交代陆照临开口说出那句话，并停在等待处，不推进守门弟子的实质答复",
        "stepIds": ["S1"]
      }
    ],
    "outcome": "陆照临说出老人让他来问山门的灯，随后停在原地等待；守门弟子尚未给出实质回应。",
    "stop": "留给玩家决定下一步：是否继续等待、补充说明、递交文书或改变行动。",
    "targetCjk": 120,
    "lengthReason": "本回合仅为一次单句告知与等待，无交锋、无新信息、无环境变化，简短收束即可。",
    "knowledge": [
      {
        "speakerId": "character_ae4cb42b9b49",
        "statement": "老人让我来问山门的灯。",
        "status": "pending",
        "sources": [],
        "afterStepId": "S1"
      }
    ],
    "observationLimits": [
      "守门弟子是否听见、是否回应、如何回应均未知，正文不得替其作答。",
      "伤者与空灯的当前状态沿用既有公开事实，不新增体征或细节。",
      "陆照临未移动、未触碰任何物品。"
    ]
  },
  "readingIntent": "brief"
}

