      "id": "O1",
      "paragraphId": "P1",
      "actor": "character_ae4cb42b9b49",
      "mode": "actual",
      "summary": "陆照临站在封山青石与山门之间，把怀里潮了边的引荐文书往衣襟深处按，贴住里衣并拢紧外袍襟口，文书没有沾到新的水痕。",
      "changes": [
        {
          "entityId": "character_ae4cb42b9b49",
          "attribute": "引荐文书状态",
          "value": "已贴身收好，未交出"
        }
      ],
      "introduced": [],
      "usedItemIds": ["item_open_letter"]
    },
    {
      "id": "O2",
      "paragraphId": "P2",
      "actor": "character_ae4cb42b9b49",
      "mode": "actual",
      "summary": "陆照临没有把文书递给任何人，也没有向守门弟子开口；收好文书后停在原处，双手垂回身侧，不再往前走，也不去碰别的什么。",
      "changes": [],
      "introduced": [],
      "usedItemIds": []
    }
  ]
}

