{
  "issues": [],
  "actions": [
    {
      "id": "A1",
      "status": "performed",
      "summary": "陆照临始终站在封山青石旁，没有向山门方向迈步，也未离开。",
      "paragraphId": "P1"
    },
    {
      "id": "A2",
      "status": "performed",
      "summary": "陆照临开口对守门弟子说，自己还没有把引荐文书交出去。",
      "paragraphId": "P2"
    },
    {
      "id": "A3",
      "status": "performed",
      "summary": "他只说了这一句，说完便闭上嘴，没有补充解释或追问。",
      "paragraphId": "P3"
    },
    {
      "id": "A4",
      "status": "performed",
      "summary": "说完后他停在原处等待，没有替守门弟子作答，也没有推进下一步行动。",
      "paragraphId": "P3"
    }
  ],
  "outcomeEvidence": [],
  "goalEvidence": [],
  "threadEvidence": [],
  "finalState": {
    "playerLocationId": "location_open_gate",
    "itemOwnerCharacterIds": {
      "item_open_letter": "character_ae4cb42b9b49"
    },
    "itemLocationIds": {}
  },
  "checkedConsequences": true,
  "eventChecks": [
    {
      "id": "O1",
      "verdict": "supported",
      "reason": "正文明确写陆照临站在封山青石旁，没有往山门方向再迈一步，与授权留在原地一致。",
      "stepIds": ["S1"],
      "changeIds": [],
      "introductionIds": []
    },
    {
      "id": "O2",
      "verdict": "supported",
      "reason": "正文描写守门弟子在几步外，披蓑衣，手按腰间灯杆，属于当场可见事实。",
      "stepIds": ["S1"],
      "changeIds": [],
      "introductionIds": ["守门弟子"]
    },
    {
      "id": "O3",
      "verdict": "supported",
      "reason": "正文直接写出陆照临开口说出“我还没有把引荐文书交出去”，与授权台词一致。",
      "stepIds": ["S1"],
      "changeIds": [],
      "introductionIds": []
    },
    {
      "id": "O4",
      "verdict": "supported",
      "reason": "正文写他闭嘴停在原处，没有去碰怀里的文书，符合只说一句并等待的约束。",
      "stepIds": ["S1"],
      "changeIds": [],
      "introductionIds": []
    },
    {
      "id": "O5",
      "verdict": "supported",
      "reason": "正文写守门弟子看着陆照临，没有立刻接话，属于当场反应，未替玩家决定下一步。",
      "stepIds": ["S1"],
      "changeIds": [],
      "introductionIds": []
    }
  ],
  "changeEvidence": [],
  "introductionEvidence": ["P1"],
  "additionalChanges": [],
  "sceneChecks": [
    {
      "paragraphId": "P1",
      "playerDecision": "none",
      "background": "supported",
      "sources": [
        {
          "id": "module:priorNarrativeBrief:paragraph-003",
          "quote": "山门外立着一块半人高的青石，石面刻着“封山”二字"
        },
        {
          "id": "module:priorNarrativeBrief:paragraph-002",
          "quote": "雨从酉时开始下。"
        }
      ],
      "quote": "",
      "issue": ""
    },
    {
      "paragraphId": "P2",
      "playerDecision": "authorized",
      "background": "none",
      "sources": [],
      "quote": "",
      "issue": ""
    },
    {
      "paragraphId": "P3",
      "playerDecision": "none",
      "background": "supported",
      "sources": [
        {
          "id": "module:priorNarrativeBrief:paragraph-004",
          "quote": "陆照临摸了摸怀里的引荐文书。纸边已经潮了。"
        }
      ],
      "quote": "",
      "issue": ""
    },
    {
      "paragraphId": "P4",
      "playerDecision": "none",
      "background": "none",
      "sources": [],
      "quote": "",
      "issue": ""
    }
  ]
}

